// Edge-case validation for the dequeue fix.
// Verifies (a) the fix throws on empty, (b) no regressions to non-empty dequeue,
// (c) the thrown error matches /empty/i as required by tests/queue.test.ts,
// (d) processNext and peek semantics are unchanged.

import { AsyncQueue } from "../src/queue.ts";

let pass = 0, fail = 0;
function check(name, cond, detail) {
  if (cond) { console.log(`PASS: ${name}`); pass++; }
  else { console.log(`FAIL: ${name} ${detail ?? ""}`); fail++; }
}

// (a) dequeue on empty throws
{
  const q = new AsyncQueue();
  let threw = false, msg = "";
  try { q.dequeue(); } catch (e) { threw = true; msg = e.message; }
  check("dequeue() throws on empty", threw, `msg=${msg}`);
  check("thrown message matches /empty/i", /empty/i.test(msg), `actual=${msg}`);
}

// (b) non-empty dequeue still works (no regression)
{
  const q = new AsyncQueue();
  q.enqueue("a");
  q.enqueue("b");
  const j1 = q.dequeue();
  const j2 = q.dequeue();
  check("dequeue returns FIFO order", j1.payload === "a" && j2.payload === "b");
  check("size is 0 after draining", q.size() === 0);
  let threwOnSecond = false;
  try { q.dequeue(); } catch { threwOnSecond = true; }
  check("dequeue throws after draining", threwOnSecond);
}

// (c) processNext still returns null on empty (not throw)
{
  const q = new AsyncQueue();
  const r = await q.processNext(async () => {});
  check("processNext returns null on empty", r === null);
}

// (d) peek returns undefined on empty (no regression)
{
  const q = new AsyncQueue();
  check("peek returns undefined on empty", q.peek() === undefined);
  q.enqueue("x");
  check("peek returns job when non-empty", q.peek() && q.peek().payload === "x");
}

// (e) error is a real Error instance (with .message)
{
  const q = new AsyncQueue();
  let e;
  try { q.dequeue(); } catch (err) { e = err; }
  check("thrown value is Error instance", e instanceof Error);
  check("Error has stack property", typeof e.stack === "string");
}

// (f) pause+resume doesn't bypass the throw
{
  const q = new AsyncQueue();
  q.pause();
  let threw = false;
  try { q.dequeue(); } catch { threw = true; }
  check("dequeue throws when paused and empty", threw);
  q.resume();
  let stillEmpty = false;
  try { q.dequeue(); } catch { stillEmpty = true; }
  check("dequeue still throws after resume on empty", stillEmpty);
}

console.log(`\nResults: ${pass} passed, ${fail} failed`);
process.exit(fail === 0 ? 0 : 1);

